import { useCallback, useReducer, useRef } from "react";

/**
 * Internal state structure for the history reducer.
 * @template T The type of the state value being tracked.
 */
export interface HistoryStateInternal<T> {
  /** Array of previous state values. */
  past: T[];
  /** The current state value. */
  present: T;
  /** Array of state values that were undone and can be redone. */
  future: T[];
}

/**
 * Union of all possible actions that can be dispatched to the history reducer.
 * @template T The type of the state value.
 */
export type HistoryAction<T> =
  | { type: "UNDO" }
  | { type: "REDO" }
  | { type: "SET"; newPresent: T }
  | { type: "CLEAR"; initialPresent: T };

/**
 * The public API returned by the useHistoryState hook.
 * @template T The type of the state value.
 */
export type HistoryState<T> = {
  /** The current value of the state. */
  state: T;
  /** Function to update the current state and push the previous state to history. */
  set: (newPresent: T) => void;
  /** Reverts the state to the previous value in history. */
  undo: () => void;
  /** Advances the state to the next value in the redo stack. */
  redo: () => void;
  /** Resets the state to the initial value and clears all history. */
  clear: () => void;
  /** Boolean indicating if there is history available to undo. */
  canUndo: boolean;
  /** Boolean indicating if there are values available to redo. */
  canRedo: boolean;
};

export const useHistoryStateReducer = <T,>(
  state: HistoryStateInternal<T>,
  action: HistoryAction<T>,
): HistoryStateInternal<T> => {
  const { past, present, future } = state;

  switch (action.type) {
    case "UNDO":
      if (past.length === 0) return state;
      return {
        past: past.slice(0, past.length - 1),
        present: past[past.length - 1],
        future: [present, ...future],
      };

    case "REDO":
      if (future.length === 0) return state;
      return {
        past: [...past, present],
        present: future[0],
        future: future.slice(1),
      };

    case "SET":
      if (action.newPresent === present) return state;
      return {
        past: [...past, present],
        present: action.newPresent,
        future: [],
      };

    case "CLEAR":
      return {
        past: [],
        present: action.initialPresent,
        future: [],
      };

    default:
      throw new Error("Unsupported action type");
  }
};

/**
 * Custom hook for managing state history, providing undo, redo, and clear functionality.
 * @category state
 * @template T - The type of the state being managed.
 * @param {T} initialPresent - The initial value to populate the state history.
 * @returns {HistoryState<T>} An object containing the current state, control functions, and status booleans.
 * @see [Documentation](https://sse-hooks.vercel.app/docs/hooks/use-history-state)
 * @public
 */
export function useHistoryState<T>(initialPresent: T): HistoryState<T> {
  const initialPresentRef = useRef(initialPresent);

  const [state, dispatch] = useReducer(
    (s: HistoryStateInternal<T>, a: HistoryAction<T>) =>
      useHistoryStateReducer<T>(s, a),
    {
      past: [],
      present: initialPresentRef.current,
      future: [],
    },
  );

  const canUndo = state.past.length !== 0;
  const canRedo = state.future.length !== 0;

  const undo = useCallback(() => {
    if (canUndo) dispatch({ type: "UNDO" });
  }, [canUndo]);

  const redo = useCallback(() => {
    if (canRedo) dispatch({ type: "REDO" });
  }, [canRedo]);

  const set = useCallback(
    (newPresent: T) => dispatch({ type: "SET", newPresent }),
    [],
  );

  const clear = useCallback(
    () =>
      dispatch({ type: "CLEAR", initialPresent: initialPresentRef.current }),
    [],
  );

  return {
    state: state.present,
    set,
    undo,
    redo,
    clear,
    canUndo,
    canRedo,
  };
}

